#[test]
fn golden_vectors_have_the_documented_shapes() {
    for v in [&RM, &WAH, &AWAH, &PUMP] {
        assert_eq!(v.ctx_in.len(), 75);
        assert_eq!(v.ctx_out.len(), 75);
        assert_eq!(v.frames_in.len(), 24);
        assert_eq!(v.frames_out.len(), 24);
        assert!(v.frames_in != v.frames_out && v.ctx_in != v.ctx_out);
    }
}
